<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SKYSHOT! — Balloon Butte</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  :root { --ink:#10142a; }
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { height:100%; overflow:hidden; background:#0b0e22; }
  #c { display:block; width:100vw; height:100vh; cursor:crosshair; }
  .px { font-family:'Press Start 2P', monospace; }
  /* Win95-style beveled panel */
  .panel {
    position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
    background:#c0c0c0; color:var(--ink);
    border-top:3px solid #fff; border-left:3px solid #fff;
    border-right:3px solid #404040; border-bottom:3px solid #404040;
    padding:6px; text-align:center; user-select:none;
  }
  .panel .in { border-top:2px solid #808080; border-left:2px solid #808080;
    border-right:2px solid #fff; border-bottom:2px solid #fff; padding:26px 34px; }
  .titlebar { background:linear-gradient(90deg,#000080,#1084d0); color:#fff;
    font-size:10px; padding:4px 8px; text-align:left; margin:-26px -34px 18px; }
  .panel h1 { font-size:26px; letter-spacing:2px; margin-bottom:14px; text-shadow:2px 2px 0 #ff5d5d; }
  .panel p { font-size:10px; line-height:2; margin-bottom:14px; }
  .panel .big { font-size:16px; margin:10px 0 16px; }
  .btn { display:inline-block; font-size:11px; padding:12px 22px; background:#c0c0c0; color:var(--ink);
    border-top:3px solid #fff; border-left:3px solid #fff; border-right:3px solid #404040; border-bottom:3px solid #404040;
    cursor:pointer; }
  .btn:active { border-top:3px solid #404040; border-left:3px solid #404040; border-right:3px solid #fff; border-bottom:3px solid #fff; }
  #hud { position:absolute; left:12px; top:12px; display:flex; gap:10px; pointer-events:none; }
  .chip { background:#c0c0c0; border-top:2px solid #fff; border-left:2px solid #fff;
    border-right:2px solid #404040; border-bottom:2px solid #404040; padding:8px 12px;
    font-size:11px; color:var(--ink); }
  .chip b { color:#000080; }
  #wave { position:absolute; left:50%; top:22%; transform:translateX(-50%); font-size:22px;
    color:#fff; text-shadow:3px 3px 0 #d0205a; opacity:0; pointer-events:none; }
  .hidden, #hud.hidden { display:none; }
  .blink { animation:bl 1s steps(2) infinite; }
  @keyframes bl { 50% { opacity:0; } }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud" class="px hidden"><div class="chip">SCORE <b id="score">0</b></div><div class="chip">COMBO <b id="combo">x1</b></div><div class="chip">LIVES <b id="lives">3</b></div></div>
<div id="wave" class="px"></div>
<div id="start" class="panel px"><div class="in">
  <div class="titlebar">C:\GAMES\SKYSHOT.EXE</div>
  <h1>SKYSHOT!</h1>
  <p>BALLOONS RISE FROM THE BUTTE.<br>LET THREE ESCAPE AND IT'S GAME OVER.<br><br>
  HOLD MOUSE — DRAW THE BOW<br>RELEASE — LOOSE THE ARROW<br>WIND SHIFTS EACH WAVE.</p>
  <div class="btn blink" id="startBtn">START</div>
</div></div>
<div id="over" class="panel px hidden"><div class="in">
  <div class="titlebar">C:\GAMES\SKYSHOT.EXE</div>
  <h1>GAME OVER</h1>
  <p class="big">SCORE <span id="final">0</span></p>
  <p>BEST <span id="best">0</span></p>
  <div class="btn blink" id="againBtn">PLAY AGAIN</div>
</div></div>
<script>
'use strict';
const cv = document.getElementById('c'), ctx = cv.getContext('2d');
let W = 0, H = 0, DPR = 1;
function resize() {
  DPR = Math.min(devicePixelRatio || 1, 2);
  W = innerWidth; H = innerHeight;
  cv.width = W * DPR; cv.height = H * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
}
addEventListener('resize', resize); resize();
const groundY = () => H * 0.84;
const archer = () => ({ x: W * 0.14, y: groundY() });

